import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
} from '@mui/material';
import { jobsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const Jobs = () => {
  const { currentUser } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [applying, setApplying] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedJob, setSelectedJob] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await jobsAPI.getJobs();
      console.log('Jobs response:', response.data); // Debug log
      setJobs(response.data || []);
    } catch (err) {
      console.error('Fetch jobs error:', err);
      setError('Failed to load jobs. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  const applyForJob = async (jobId) => {
    try {
      setApplying(true);
      setError('');
      setSuccess('');
      
      const response = await jobsAPI.applyForJob(jobId);
      setSuccess(response.data.message || 'Successfully applied for the job!');
      setDialogOpen(false);
      
      // Refresh jobs to update application status if needed
      fetchJobs();
    } catch (err) {
      console.error('Apply job error:', err);
      setError(err.response?.data?.error || 'Failed to apply for job. Please try again.');
    } finally {
      setApplying(false);
    }
  };

  const openJobDetails = (job) => {
    setSelectedJob(job);
    setDialogOpen(true);
  };

  const closeDialog = () => {
    setDialogOpen(false);
    setSelectedJob(null);
    setError('');
    setSuccess('');
  };

  const getJobTypeColor = (jobType) => {
    switch (jobType) {
      case 'full-time': return 'primary';
      case 'part-time': return 'secondary';
      case 'contract': return 'success';
      case 'internship': return 'warning';
      default: return 'default';
    }
  };

  const formatSalary = (salary) => {
    if (!salary) return 'Negotiable';
    return salary;
  };

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '50vh' }}>
        <Box textAlign="center">
          <CircularProgress size={60} />
          <Typography variant="h6" sx={{ mt: 2 }}>Loading jobs...</Typography>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Job Opportunities
      </Typography>
      <Typography variant="body1" color="textSecondary" sx={{ mb: 3 }}>
        Browse and apply for jobs from our partner companies
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess('')}>
          {success}
        </Alert>
      )}

      <Grid container spacing={3}>
        {jobs.length === 0 ? (
          <Grid item xs={12}>
            <Paper elevation={3} sx={{ padding: 4, textAlign: 'center' }}>
              <Typography variant="h6" color="textSecondary">
                No jobs available at the moment
              </Typography>
              <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                Companies haven't posted any jobs yet. Check back later for new opportunities.
              </Typography>
            </Paper>
          </Grid>
        ) : (
          jobs.map((job) => (
            <Grid item xs={12} md={6} key={job.id}>
              <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                <CardContent sx={{ flexGrow: 1 }}>
                  <Typography variant="h6" gutterBottom>
                    {job.title}
                  </Typography>
                  <Typography variant="body2" color="textSecondary" gutterBottom>
                    {job.company?.name || 'Unknown Company'} • {job.location || 'Location not specified'}
                  </Typography>
                  <Typography variant="body2" paragraph sx={{ flexGrow: 1 }}>
                    {job.description && job.description.length > 120 
                      ? `${job.description.substring(0, 120)}...` 
                      : job.description || 'No description available'
                    }
                  </Typography>
                  
                  <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
                    {job.jobType && (
                      <Chip 
                        label={job.jobType} 
                        color={getJobTypeColor(job.jobType)}
                        size="small"
                      />
                    )}
                    {job.salary && (
                      <Chip 
                        label={formatSalary(job.salary)} 
                        variant="outlined"
                        size="small"
                      />
                    )}
                    {job.deadline && new Date(job.deadline) > new Date() && (
                      <Chip 
                        label={`Apply by ${new Date(job.deadline).toLocaleDateString()}`}
                        color="info"
                        size="small"
                        variant="outlined"
                      />
                    )}
                  </Box>

                  <Box sx={{ display: 'flex', gap: 1, mt: 'auto' }}>
                    <Button
                      variant="outlined"
                      onClick={() => openJobDetails(job)}
                      size="small"
                      fullWidth
                    >
                      View Details
                    </Button>
                    <Button
                      variant="contained"
                      onClick={() => applyForJob(job.id)}
                      disabled={applying}
                      size="small"
                      fullWidth
                    >
                      {applying ? 'Applying...' : 'Apply Now'}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))
        )}
      </Grid>

      {/* Job Details Dialog */}
      <Dialog open={dialogOpen} onClose={closeDialog} maxWidth="md" fullWidth>
        <DialogTitle>
          {selectedJob?.title}
        </DialogTitle>
        <DialogContent>
          {selectedJob && (
            <Box>
              <Typography variant="h6" gutterBottom color="primary">
                {selectedJob.company?.name || 'Unknown Company'}
              </Typography>
              
              <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
                {selectedJob.jobType && (
                  <Chip 
                    label={selectedJob.jobType} 
                    color={getJobTypeColor(selectedJob.jobType)}
                  />
                )}
                {selectedJob.location && (
                  <Chip 
                    label={selectedJob.location} 
                    variant="outlined"
                  />
                )}
                {selectedJob.salary && (
                  <Chip 
                    label={formatSalary(selectedJob.salary)} 
                    color="success"
                    variant="outlined"
                  />
                )}
              </Box>

              <Typography variant="body1" paragraph>
                {selectedJob.description || 'No description available.'}
              </Typography>

              {selectedJob.requirements && (
                <>
                  <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>
                    Requirements
                  </Typography>
                  <Box sx={{ mb: 2 }}>
                    {selectedJob.requirements.educationLevel && (
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        <strong>Education Level:</strong> {selectedJob.requirements.educationLevel}
                      </Typography>
                    )}
                    {selectedJob.requirements.minExperience !== undefined && (
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        <strong>Minimum Experience:</strong> {selectedJob.requirements.minExperience} year(s)
                      </Typography>
                    )}
                    {selectedJob.requirements.skills && selectedJob.requirements.skills.length > 0 && (
                      <Box sx={{ mb: 1 }}>
                        <Typography variant="body2">
                          <strong>Required Skills:</strong>
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                          {selectedJob.requirements.skills.map((skill, index) => (
                            <Chip key={index} label={skill} size="small" variant="outlined" />
                          ))}
                        </Box>
                      </Box>
                    )}
                    {selectedJob.requirements.certificates && selectedJob.requirements.certificates.length > 0 && (
                      <Box sx={{ mb: 1 }}>
                        <Typography variant="body2">
                          <strong>Required Certificates:</strong>
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                          {selectedJob.requirements.certificates.map((cert, index) => (
                            <Chip key={index} label={cert} size="small" variant="outlined" />
                          ))}
                        </Box>
                      </Box>
                    )}
                  </Box>
                </>
              )}

              {selectedJob.qualifications && selectedJob.qualifications.length > 0 && (
                <>
                  <Typography variant="h6" gutterBottom>
                    Qualifications
                  </Typography>
                  <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                    {selectedJob.qualifications.map((qual, index) => (
                      <Typography component="li" variant="body2" key={index}>
                        {qual}
                      </Typography>
                    ))}
                  </Box>
                </>
              )}

              {selectedJob.deadline && (
                <Typography variant="body2" color="textSecondary">
                  <strong>Application Deadline:</strong> {new Date(selectedJob.deadline).toLocaleDateString()}
                </Typography>
              )}
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeDialog}>Close</Button>
          <Button 
            variant="contained" 
            onClick={() => applyForJob(selectedJob?.id)}
            disabled={applying}
          >
            {applying ? 'Applying...' : 'Apply for this Job'}
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Jobs;
